UPDATE live_stream
SET status = #{targetStatus},
    version = version + 1,
    started_at = CASE WHEN #{targetStatus} = 'LIVE' THEN CURRENT_TIMESTAMP(6) ELSE started_at END,
    ended_at = CASE WHEN #{targetStatus} = 'ENDED' THEN CURRENT_TIMESTAMP(6) ELSE ended_at END
WHERE id = #{streamId}
  AND creator_id = #{creatorId}
  AND status = #{expectedStatus}
